-- ============================================================================
-- PARTIE 15 — Contenu du module 2 « Émotions, pleurs, cadre sans violence » (3 séquences)
-- Source : Projet pédagogique Koalakids (pleurs et émotions, port d'attache et
-- boussole, cadre commun, ne pas punir ni isoler).
-- Script reconstitué à partir de la base (contenu publié).
-- Relançable : la trame est remplacée, les blocs ne sont ajoutés qu'une fois.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 15.1a Trame de la séquence 1/3 (Apport). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Un pleur dit quelque chose. Avant de chercher à le faire cesser, on cherche ce que l'enfant exprime.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire ce que peut exprimer un pleur et de répondre d'abord en port d'attache (sécuriser), puis en boussole (nommer l'émotion et soutenir l'enfant), sans chercher à la faire cesser.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 1, "attendu": "Besoins affectifs et émotionnels"}, "duree_min": 45, "materiel": ["Fiche « Trois postures » (1 par personne)", "Paperboard", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Présenter les 3 séances du module : apport, analyse d'une situation vécue, test d'une pratique.", "Chacun pense à un pleur ou à une colère de la semaine, sans le raconter."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Un pleur est un message : avant de chercher à le faire cesser, je cherche ce qu'il dit.", "idees": ["Un pleur est une sorte de système d'alarme : l'enfant ne peut pas apaiser seul ce qu'il ressent (fatigue, faim, besoin de lien, émotion trop grosse). Ce n'est ni une exagération ni une volonté de nuire ou de manipuler.", "Port d'attache : l'adulte répond, console, reste disponible. L'enfant se calme et apprend qu'il peut compter sur lui. On ne laisse pas un enfant seul au milieu de sa tempête.", "Boussole : je nomme l'émotion, je la reconnais comme légitime, je soutiens l'enfant pour l'apprivoiser plutôt que de la faire cesser, et je lui indique la direction du réconfort. Dans notre projet : on ne punit pas, on n'isole pas."], "support": "Fiche « Trois postures » (1 page : port d'attache, phare, boussole). Aujourd'hui, l'accent est mis sur le port d'attache et la boussole."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir une situation de la semaine, vécue sur le site. On analyse la pratique, pas la personne.", "questions": ["Que s'est-il passé ? (les faits, sans jugement)", "Quel besoin de l'enfant ?", "Que faire autrement ? Quelle posture ?"]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "amorce": "Cette semaine, je…", "consigne": "Un engagement concret par personne, écrit sur la fiche de trace.", "consignes": ["Exemple : m'accroupir et nommer ce que je vois avant de proposer quoi que ce soit.", "Exemple : noter un pleur et le besoin que j'y devine."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes).", "Annoncer la séance 2/3 : analyse d'une situation vécue de pleurs ou de colère, apportée par l'équipe."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 2 % 1/3 %';
-- FIN 15.1a

-- ---------------------------------------------------------------------------
-- 15.1b Blocs de la séquence 1/3. Attendu : 4 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Un pleur est un message", "paragraphes": ["Quand quelque chose ne va pas pour lui, le jeune enfant pleure. Ses pleurs sont en quelque sorte **un système d'alarme** : il est dans un état émotionnel qu'il ne peut pas contrôler seul, et il a besoin de l'adulte pour s'apaiser.", "Cette première séance pose un repère simple : avant de chercher à faire cesser un pleur, on cherche ce qu'il dit."]}$kk$),
  (1,'retenir',$kk${"titre": "À retenir", "points": ["**Un pleur dit un besoin** (fatigue, faim, besoin de lien, émotion trop grosse). Ce n'est ni une exagération, ni une volonté de nuire ou de manipuler.", "**Port d'attache :** je réponds, je console, je reste disponible. Je ne laisse pas l'enfant seul au milieu de sa tempête.", "**Boussole :** je nomme l'émotion, je la reconnais comme légitime, je soutiens l'enfant pour l'apprivoiser plutôt que de la faire cesser, et je lui indique la direction du réconfort. On ne punit pas, on n'isole pas."]}$kk$),
  (2,'reflexion',$kk${"question": "Pensez à un pleur ou à une colère de cette semaine. Qu'est-ce que l'enfant disait, selon vous ? Qu'avez-vous fait en premier ?", "sous_titre": "Il n'y a pas de bonne ou de mauvaise réponse : on cherche à comprendre.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (3,'essayer',$kk${"label": "À essayer cette semaine", "titre": "Avant d'agir, trois temps", "etapes": [{"titre": "Je me mets à sa hauteur.", "texte": "Je m'approche, je m'accroupis, je regarde l'enfant."}, {"titre": "Je nomme ce que je vois.", "texte": "« Tu es triste de quitter maman ce matin, je comprends. »"}, {"titre": "Je reste disponible.", "texte": "Je console au besoin et, quand l'enfant est prêt, je propose un choix possible pour l'aider à sortir de sa frustration."}], "note": "Choisissez un seul de ces gestes et testez-le toute la semaine."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 2 % 1/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 15.1b

-- ---------------------------------------------------------------------------
-- 15.2a Trame de la séquence 2/3 (Analyse d'une situation vécue). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Un cadre commun et protecteur, des limites dites simplement : on ne punit pas, on n'isole pas.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire comment poser un cadre commun face à une colère ou à un conflit entre enfants sans punir ni isoler, en accompagnant les deux enfants.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 1, "attendu": "Besoins affectifs et émotionnels"}, "duree_min": 45, "materiel": ["Paperboard (pour noter les limites communes de l'équipe)", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Retour sur la semaine : chacun dit en une phrase ce qu'il a essayé de son engagement « Cette semaine, je… », sans l'évaluer.", "Demander qui apporte la situation à analyser."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Poser un cadre, ce n'est ni punir ni isoler : l'adulte reprend l'enfant, l'accompagne et reste près de lui.", "idees": ["Le cadre est commun à toute l'équipe, protecteur et compréhensible : mêmes limites, mêmes façons d'intervenir, pas d'injonctions contradictoires (des tentations d'un côté, des interdits de l'autre). Les grands interdits : ne pas se faire mal ni faire mal aux autres, ne pas détruire ni prendre ce qui ne nous appartient pas.", "Quand un interdit n'est pas respecté, on reprend l'enfant à sa hauteur, avec un visage qui correspond à ce que l'on dit, sans grand discours ni excuses forcées, et on accompagne les deux enfants : tous deux sont en apprentissage.", "Un enfant n'est jamais « méchant » : il fait des expériences. On ne punit pas, on n'isole pas. Toute violence physique ou verbale et tout isolement sont une faute professionnelle. Avant d'en arriver là : parler de ses propres émotions, demander de l'aide, analyser en équipe."], "support": "Projet pédagogique Koalakids, « Que faire concrètement pour permettre aux enfants d'apprendre les règles sociales ? »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir une colère, un conflit ou un pleur vécus cette semaine sur le site, sans nommer l'enfant. On analyse la pratique, pas la personne.", "questions": ["Que s'est-il passé ? (les faits, sans jugement)", "Quel besoin de l'enfant ? Quelle émotion ?", "Le cadre était-il clair et commun à l'équipe ?", "Ai-je repris l'enfant sans le punir ni l'isoler ? Que faire autrement ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : me mettre à hauteur de l'enfant et dire la limite en une phrase, avec un visage qui correspond.", "Exemple : m'occuper des deux enfants après un conflit.", "Exemple : repérer avec l'équipe une limite que nous n'appliquons pas tous de la même façon."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Annoncer la séance 3/3 : retour d'expérience sur la pratique testée, avec un focus sur l'accompagnement des émotions."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 2 % 2/3 %';
-- FIN 15.2a

-- ---------------------------------------------------------------------------
-- 15.2b Blocs de la séquence 2/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Un cadre qui protège, sans punir", "paragraphes": ["Un jeune enfant apprend les règles sociales surtout par imprégnation et par imitation. Il a besoin d'un cadre **commun, protecteur et compréhensible**, et d'adultes qui le reprennent sans le blesser.", "Cette séance propose d'analyser une situation vécue en regardant ce que l'adulte a fait : le cadre était-il clair, et l'enfant a-t-il été accompagné plutôt que puni ou isolé ?"]}$kk$),
  (1,'scenes',$kk${"titre": "Trois situations que vous reconnaîtrez", "items": [{"lettre": "A", "titre": "Il pousse un camarade pour récupérer un camion", "texte": "Sacha a poussé Jade pour récupérer un camion. Un collègue lui dit : « Ce n'est pas gentil, tu vas t'excuser. »", "analyse": "à cet âge, l'enfant n'est pas encore en capacité de réfléchir à son geste ni de s'excuser sur commande. On le reprend à sa hauteur, on dit simplement que faire mal n'est pas accepté, et on accompagne les deux enfants : celui qui a poussé et celui qui a été poussé. Tous deux sont en apprentissage."}, {"lettre": "B", "titre": "Elle crie et on l'emmène seule dans une autre pièce", "texte": "Jade crie et se jette par terre après avoir perdu le camion. Un collègue l'emmène seule dans une autre pièce en lui disant de se calmer.", "analyse": "isoler un enfant est une faute professionnelle, et le laisser seul avec une émotion qu'il ne peut pas apaiser seul ne l'aide pas à la réguler. On reste près d'elle, on nomme ce qu'elle ressent, on la console au besoin."}, {"lettre": "C", "titre": "Deux adultes, deux règles", "texte": "Le matin, Noé a le droit de grimper sur le banc avec un collègue. L'après-midi, un autre adulte le lui interdit en haussant le ton.", "analyse": "des règles qui changent d'un adulte à l'autre sont difficiles à comprendre pour un jeune enfant. On définit en équipe les limites et les façons d'intervenir, et on évite de placer des tentations d'un côté et des interdits de l'autre."}]}$kk$),
  (2,'comparaison',$kk${"intro": "Face à une colère ou à un conflit entre enfants.", "plutot": ["Poser des limites claires, communes à toute l'équipe.", "Reprendre l'enfant à sa hauteur, avec un visage et des mots qui concordent.", "Accompagner les deux enfants d'un conflit.", "Rester près d'un enfant en pleine tempête émotionnelle."], "eviter": ["Punir ou isoler un enfant.", "Exiger des excuses ou faire un grand discours.", "Lui mettre une étiquette (« méchant », « vicieux »).", "Changer de règle d'un adulte à l'autre."]}$kk$),
  (3,'reflexion',$kk${"question": "Dans votre équipe, y a-t-il une limite que chacun applique à sa façon ? Qu'est-ce qui vous aiderait à vous accorder ?", "sous_titre": "Il s'agit de décrire, pas de juger. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer cette semaine", "titre": "Reprendre sans punir", "etapes": [{"titre": "Me mettre à sa hauteur.", "texte": "Je m'accroupis et je prends un visage qui correspond à ce que je dis."}, {"titre": "Dire la limite simplement.", "texte": "Faire mal n'est pas accepté. Pas de grand discours, pas d'excuses forcées."}, {"titre": "Accompagner les deux.", "texte": "Je m'occupe de l'enfant qui a été touché et de celui qui a agi : tous deux apprennent."}], "note": "Choisissez un seul de ces gestes et testez-le toute la semaine."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 2 % 2/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 15.2b

-- ---------------------------------------------------------------------------
-- 15.3a Trame de la séquence 3/3 (Test d'une pratique et retour d'expérience). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Nommer, reconnaître, soutenir : l'enfant apprend à apprivoiser ses émotions, et l'adulte a besoin de l'équipe pour tenir.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire ce qu'a changé la pratique testée pour l'enfant, et l'équipe a choisi une pratique commune pour accompagner les émotions des enfants (nommer, reconnaître, soutenir).", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 1, "attendu": "Besoins affectifs et émotionnels"}, "duree_min": 45, "materiel": ["Fiche de trace", "Engagements de la séance 2", "Paperboard"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Chacun relit son engagement de la séance 2 (« Cette semaine, je… »).", "Rappeler la règle : on raconte ce qu'on a fait, on ne se juge pas."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Ce que je nomme et reconnais aujourd'hui, l'enfant apprendra peu à peu à le nommer et à le réguler lui-même.", "idees": ["On accompagne l'émotion en la nommant (« Tu es triste de quitter maman ce matin, je comprends »), en la reconnaissant comme légitime, en consolant au besoin, et parfois en proposant un choix possible pour sortir de la frustration. On soutient l'enfant, on ne cherche pas à faire cesser son émotion.", "On nomme aussi ce que l'on ressent dans la relation à l'enfant (« Je suis content de te voir ce matin ») : l'enfant comprend le sens des émotions et pourra les utiliser à son tour.", "Pour se laisser toucher par les émotions des enfants sans les nier ni les enflammer, l'adulte a besoin de maîtriser les siennes : en parler, demander de l'aide quand on n'en peut plus, analyser les difficultés en équipe."], "support": "Projet pédagogique Koalakids, « Que faire concrètement pour accompagner les enfants dans leurs émotions ? »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site (retour d'expérience)", "consigne": "Chacun raconte en une minute la pratique qu'il a testée. On cherche ce qui s'est passé, pas qui a bien ou mal fait.", "questions": ["Qu'ai-je testé, et dans quelle situation ?", "Qu'a fait l'enfant quand j'ai nommé son émotion ? Qu'est-ce qui a changé, même un peu ?", "Qu'est-ce qui a été difficile ?", "Que gardons-nous en équipe ? Que changeons-nous ?"]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Choisir ensemble une pratique commune à tenir pendant deux semaines, puis un engagement par personne.", "amorce": "Cette semaine, je…", "consignes": ["Pratique commune : une phrase que chacun peut décrire de la même façon.", "Chacun s'engage sur un geste précis, noté sur la fiche de trace."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Tour de table : ce que je retiens du module 2. Annoncer le prochain module du programme et la date de la première séance."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 2 % 3/3 %';
-- FIN 15.3a

-- ---------------------------------------------------------------------------
-- 15.3b Blocs de la séquence 3/3. Attendu : 4 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Prêter sa boussole", "paragraphes": ["Quand une émotion submerge l'enfant, il a besoin d'un adulte à ses côtés, comme une **boussole** : il nomme ce que l'enfant vit, le reconnaît comme légitime et l'oriente vers le réconfort.", "En lui prêtant sa boussole, l'adulte permet à l'enfant de trouver la sienne. Cette dernière séance sert à regarder ce que vous avez testé, et à choisir **une pratique commune**."]}$kk$),
  (1,'retenir',$kk${"titre": "À retenir", "points": ["**Nommer :** « Tu es triste de quitter maman ce matin, je comprends. » L'enfant apprend peu à peu ce qu'il vit.", "**Reconnaître comme légitime :** une émotion est toujours vraie. Ce n'est ni une exagération ni une volonté de manipuler.", "**Soutenir, pas faire cesser :** nos mots, notre empathie, notre tendresse au besoin, et parfois un choix possible pour sortir de la frustration."]}$kk$),
  (2,'reflexion',$kk${"question": "Quand l'émotion d'un enfant vous touche ou vous épuise, qu'est-ce qui vous aide à tenir ? À qui pouvez-vous en parler dans l'équipe ?", "sous_titre": "Parler de ses propres émotions et demander de l'aide permet de continuer à bien accompagner. Il n'y a pas de bonne réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (3,'essayer',$kk${"label": "À essayer après la séance", "titre": "Une pratique commune", "etapes": [{"titre": "La choisir ensemble.", "texte": "Un geste simple, que chacun décrit de la même façon."}, {"titre": "La tenir deux semaines.", "texte": "Sans chercher la perfection : on note ce qui marche et ce qui coince."}, {"titre": "En reparler en équipe.", "texte": "À la prochaine réunion, quelques minutes pour dire ce qu'on garde."}], "note": "Toute pratique commune se décrit en une phrase."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 2 % 3/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 15.3b

-- ---------------------------------------------------------------------------
-- 15c Contrôle (lecture seule). Attendu : 3 séquences, blocs 4 / 5 / 4.
-- ---------------------------------------------------------------------------
select m.titre, m.publie, (m.trame->>'objectif') is not null as objectif_ok,
       (select count(*) from public.bloc b where b.module_id = m.id) as blocs
from public.module m where m.titre like 'Module 2 %/3 %' order by m.ordre;
-- FIN 15c
